window.OSHA_QUESTIONS = [
  { id: "in-01", category: "intro", topic: "Ley OSH", q: "La Occupational Safety and Health Act que creó OSHA se aprobó en:", choices: ["1960", "1970", "1986", "2001"], a: 1, why: "El Congreso aprobó la OSH Act en 1970. OSHA abrió en 1971 bajo el Departamento del Trabajo de EE. UU." },
  { id: "in-02", category: "intro", topic: "Agencia", q: "¿OSHA es una agencia de cuál departamento federal?", choices: ["Departamento de Comercio", "Departamento de Transporte", "Departamento del Trabajo", "Departamento de Seguridad Nacional"], a: 2, why: "OSHA forma parte del Departamento del Trabajo de EE. UU. El Subsecretario del Trabajo para OSHA dirige la agencia." },
  { id: "in-03", category: "intro", topic: "Cláusula de deber general", q: "La Sección 5(a)(1) de la OSH Act — la Cláusula de deber general — exige que el empleador:", choices: ["Pague horas extras por todas las juntas de seguridad", "Proporcione un lugar de trabajo libre de peligros reconocidos que causen o puedan causar muerte o daño físico grave", "Entregue tarjetas OSHA 30 a cada nuevo empleado en 24 horas", "Inspeccione cada herramienta a diario con una lista escrita aunque no se use"], a: 1, why: "Cuando no aplica una norma específica, la Cláusula de deber general igual exige que el empleador atienda peligros graves reconocidos." },
  { id: "in-04", category: "intro", topic: "Derechos del trabajador", q: "¿Cuál de las siguientes es un derecho del trabajador bajo OSHA?", choices: ["El derecho a un lugar de trabajo seguro y a plantear preocupaciones de seguridad sin represalias", "El derecho a saltarse la capacitación requerida si está ocupado", "El derecho a rechazar todo el EPP", "El derecho a pedir que las lesiones no se anoten en el registro de OSHA"], a: 0, why: "Los trabajadores pueden presentar quejas, participar en inspecciones, recibir capacitación y estar protegidos contra represalias según la Sección 11(c)." },
  { id: "in-05", category: "intro", topic: "Quejas", q: "Un trabajador que cree que hay un peligro grave puede:", choices: ["Solo decírselo a un compañero", "Presentar una queja confidencial ante OSHA", "Esperar hasta que ocurra una lesión", "Llamar siempre al departamento de bomberos en lugar de OSHA"], a: 1, why: "Cualquier persona puede presentar una queja ante OSHA. Los trabajadores pueden pedir que su nombre se mantenga confidencial respecto al empleador." },
  { id: "in-06", category: "intro", topic: "Notificación de fatalidad", q: "El empleador debe reportar a OSHA una fatalidad relacionada con el trabajo dentro de:", choices: ["1 hora", "8 horas", "24 horas", "7 días"], a: 1, why: "29 CFR 1904.39: reporte las fatalidades dentro de las 8 horas de enterarse." },
  { id: "in-07", category: "intro", topic: "Notificación de lesión grave", q: "La hospitalización, una amputación o la pérdida de un ojo debe reportarse a OSHA dentro de:", choices: ["8 horas", "24 horas", "7 días", "30 días"], a: 1, why: "Estas lesiones graves deben reportarse dentro de 24 horas. Las fatalidades siguen el plazo de 8 horas." },
  { id: "in-08", category: "intro", topic: "Publicación del 300A", q: "El resumen anual OSHA 300A debe publicarse desde:", choices: ["el 1 de enero hasta el 31 de enero", "el 1 de febrero hasta el 30 de abril", "el 1 de julio hasta el 30 de septiembre", "solo el día de una inspección"], a: 1, why: "Los empleadores cubiertos publican el 300A en un lugar visible del 1 de febrero al 30 de abril." },
  { id: "in-09", category: "intro", topic: "Prioridad de inspección", q: "¿Qué tipo de inspección tiene la mayor prioridad de OSHA?", choices: ["Inspecciones programadas planificadas", "Quejas de empleados", "Peligro inminente", "Inspecciones de seguimiento"], a: 2, why: "El orden de prioridad es, en general, peligro inminente, luego fatalidad/catástrofe, quejas/referencias y después inspecciones programadas." },
  { id: "in-10", category: "intro", topic: "Citaciones", q: "¿Cuánto tiempo tiene el empleador, en general, para impugnar una citación de OSHA?", choices: ["7 días calendario", "15 días hábiles", "30 días calendario", "90 días"], a: 1, why: "El empleador tiene 15 días hábiles desde que recibe la citación para presentar un Notice of Contest." },
  { id: "in-11", category: "intro", topic: "Denunciante", q: "La Sección 11(c) de la OSH Act protege a los trabajadores que:", choices: ["Ignoran los procedimientos de bloqueo", "Sufren represalias por plantear preocupaciones de seguridad o participar en actividades de OSHA", "Se niegan a usar la protección auditiva requerida", "Alteran los registros de lesiones a petición del supervisor"], a: 1, why: "Es ilegal despedir, degradar o tomar represalias de otro modo contra un trabajador por una actividad de seguridad protegida." },
  { id: "in-12", category: "intro", topic: "Capacitación", q: "¿Quién es responsable de proporcionar la capacitación de seguridad de OSHA que se exige a los trabajadores?", choices: ["Los inspectores de OSHA en cada visita", "El empleador", "Solo el sindicato del trabajador", "Solo el fabricante del equipo"], a: 1, why: "El empleador debe capacitar a los trabajadores sobre los peligros y las protecciones requeridas en un idioma y vocabulario que comprendan." },
  { id: "in-13", category: "intro", topic: "Planes estatales", q: "Un plan estatal de OSHA debe ser:", choices: ["Más débil que OSHA federal para que los negocios compitan", "Al menos tan eficaz como OSHA federal", "Limitado solo a la construcción", "Opcional para empleados públicos en todos los estados"], a: 1, why: "Los State Plans que cubren a trabajadores del sector privado deben ser al menos tan eficaces como OSHA federal y pueden ser más estrictos." },
  { id: "in-14", category: "intro", topic: "Tarjetas Outreach", q: "Una tarjeta Outreach OSHA 10 o 30:", choices: ["Es una licencia federal para supervisar cualquier obra", "Se emite solo después de completar las horas requeridas con un instructor autorizado; no sustituye el curso oficial", "Vence 30 días después del examen", "Permite omitir la protección contra caídas en trabajo residencial"], a: 1, why: "Outreach es capacitación de concientización. Solo instructores autorizados emiten tarjetas del DOL después de las horas del curso. Los cuestionarios de práctica no emiten tarjeta." },
  { id: "in-15", category: "intro", topic: "Registro", q: "El formulario OSHA 300 se usa para:", choices: ["Solicitar una variación", "Registrar lesiones y enfermedades relacionadas con el trabajo", "Reportar una fatalidad por teléfono", "Certificar operadores de grúa"], a: 1, why: "El Formulario 300 es el registro. El Formulario 301 es el informe del incidente. El Formulario 300A es el resumen anual." },
  { id: "ff-01", category: "focusFour", topic: "Los cuatro", q: "Los peligros “Focus Four” de construcción de OSHA son:", choices: ["Ruido, calor, sílice y plomo", "Caídas, golpes (struck-by), atrapamiento y electrocución", "Incendio, espacio confinado, LOTO y montacargas", "Asbesto, radiación, láseres y vibración"], a: 1, why: "Estos cuatro causan la mayoría de las fatalidades en construcción. Los cursos Outreach los enfatizan mucho." },
  { id: "ff-02", category: "focusFour", topic: "Principal causa de muerte", q: "¿Cuál peligro Focus Four es la principal causa de muerte en la construcción?", choices: ["Electrocución", "Atrapamiento", "Caídas", "Golpes (struck-by)"], a: 2, why: "Las caídas desde altura representan de forma constante la mayor parte de las fatalidades en construcción." },
  { id: "ff-03", category: "focusFour", topic: "Golpes (struck-by)", q: "Los peligros de golpes (struck-by) incluyen ser golpeado por:", choices: ["Solo herramientas de mano que caen desde 6 pies o más", "Objetos que vuelan, caen, se balancean o ruedan", "Solo vehículos de más de 26,001 libras", "Solo objetos de más de 50 libras"], a: 1, why: "Las grúas, los vehículos, la mampostería, las herramientas de carga explosiva y los materiales que caen son fuentes comunes de golpes." },
  { id: "ff-04", category: "focusFour", topic: "Atrapamiento", q: "Una fatalidad clásica por atrapamiento es:", choices: ["El derrumbe de una pared de zanja que entierra a un trabajador", "Una quemadura de sol", "Pérdida auditiva a lo largo de 20 años", "Un corte de papel"], a: 0, why: "Los derrumbes de zanjas, la maquinaria sin resguardo y las estructuras que colapsan son eventos de atrapamiento." },
  { id: "ff-05", category: "focusFour", topic: "Electrocución", q: "La electrocución en obras de construcción casi siempre involucra:", choices: ["Contacto con líneas eléctricas aéreas o cordones y herramientas dañados", "Solo rayos", "Solo baterías de vehículos de 12 voltios", "Estática de tubería de plástico"], a: 0, why: "Las grúas, las escaleras y el revestimiento cerca de líneas aéreas, más los cordones defectuosos y la falta de GFCI, causan muchas muertes." },
  { id: "ff-06", category: "focusFour", topic: "Prevención", q: "La forma más eficaz de controlar un peligro Focus Four suele ser:", choices: ["Depender solo del EPP", "Eliminar el peligro o controlarlo con ingeniería (por ejemplo, barandales en lugar de esperar que recuerden el arnés)", "Poner un cartel y no hacer nada más", "Esperar hasta después de un incidente"], a: 1, why: "Jerarquía de controles: la eliminación y la ingeniería superan al EPP. Un barandal supera a un arnés que tal vez no esté amarrado." },
  { id: "ff-07", category: "focusFour", topic: "Cascos", q: "Los cascos ayudan principalmente contra cuál peligro Focus Four?", choices: ["Atrapamiento por derrumbe de zanja", "Golpes (struck-by) por objetos que caen o vuelan", "Electrocución por líneas aéreas en todos los casos", "Caídas desde el borde de un techo"], a: 1, why: "Los cascos (y mantenerse fuera de la zona de caída) reducen lesiones en la cabeza por golpes. No son protección contra caídas." },
  { id: "fp-01", category: "fallProtection", topic: "Umbral en construcción", q: "En construcción, la protección contra caídas se exige en general cuando las superficies de trabajo y circulación están a qué altura sobre un nivel inferior?", choices: ["4 pies", "6 pies", "10 pies", "15 pies"], a: 1, why: "29 CFR 1926.501: 6 pies es el umbral general en construcción. Andamios, montaje de acero y algunas otras actividades tienen alturas distintas." },
  { id: "fp-02", category: "fallProtection", topic: "Industria general", q: "En industria general, la protección contra caídas se exige en general a:", choices: ["4 pies", "6 pies", "10 pies", "solo a 15 pies"], a: 0, why: "29 CFR 1910.28 usa en general 4 pies para lados y bordes sin protección." },
  { id: "fp-03", category: "fallProtection", topic: "Sistemas convencionales", q: "Los tres sistemas convencionales de protección contra caídas son:", choices: ["Casco, guantes y botas", "Barandales, redes de seguridad y sistemas personales de detención de caídas", "Solo cinta de advertencia, conos y un vigía", "Escaleras, rampas y tramos de escalera"], a: 1, why: "1926.501/502 identifican sistemas de barandal, redes de seguridad y detención personal de caídas como protección convencional." },
  { id: "fp-04", category: "fallProtection", topic: "Barandal superior", q: "El barandal superior en construcción debe tener una altura de aproximadamente:", choices: ["21 pulgadas ± 3 pulgadas", "42 pulgadas ± 3 pulgadas (39 a 45 pulgadas)", "60 pulgadas exactas", "12 pulgadas"], a: 1, why: "1926.502(b): el borde superior a 42 pulgadas más o menos 3 pulgadas sobre la superficie de trabajo y circulación." },
  { id: "fp-05", category: "fallProtection", topic: "Resistencia del barandal superior", q: "Un barandal superior debe resistir una fuerza de al menos:", choices: ["50 libras", "100 libras", "200 libras", "5,000 libras"], a: 2, why: "Barandales superiores: 200 lb hacia afuera/abajo. Barandales intermedios: 150 lb. Rodapiés: 50 lb." },
  { id: "fp-06", category: "fallProtection", topic: "Anclaje", q: "Un anclaje de detención personal de caídas debe ser capaz de soportar al menos:", choices: ["250 libras", "1,000 libras", "5,000 libras por empleado sujeto, o estar diseñado por una persona calificada con un factor de seguridad de al menos dos", "Solo el peso corporal del trabajador"], a: 2, why: "1926.502(d)(15): 5,000 lb por empleado, o un diseño de persona calificada con un factor de al menos dos." },
  { id: "fp-07", category: "fallProtection", topic: "Caída libre", q: "La detención personal de caídas debe limitar en general la caída libre a:", choices: ["2 pies", "6 pies", "12 pies", "30 pies"], a: 1, why: "La caída libre se limita a 6 pies, y el sistema debe impedir el contacto con un nivel inferior." },
  { id: "fp-08", category: "fallProtection", topic: "Redes de seguridad", q: "Las redes de seguridad deben instalarse lo más cerca posible bajo la superficie de trabajo, pero a no más de:", choices: ["6 pies por debajo", "10 pies por debajo", "30 pies por debajo", "50 pies por debajo"], a: 2, why: "1926.502(c)(1): redes a no más de 30 pies por debajo. Más cerca es mejor." },
  { id: "fp-09", category: "fallProtection", topic: "Cubiertas de huecos", q: "Las cubiertas de huecos deben estar:", choices: ["Cualquier pedazo de cartón", "Aseguradas, marcadas “HOLE” o “COVER” o similar, y capaces de soportar al menos el doble de la carga prevista", "Solo pintadas de amarillo, sin requisito de resistencia", "Opcionales si el hueco mide menos de 12 pulgadas"], a: 1, why: "1926.502(i): marque o codifique por color las cubiertas, asegúrelas y diséñelas para al menos el doble de la carga de empleados, equipo y materiales." },
  { id: "fp-10", category: "fallProtection", topic: "Andamios", q: "En andamios, la protección contra caídas se exige en general a:", choices: ["4 pies", "6 pies", "10 pies", "15 pies"], a: 2, why: "1926.451(g): 10 pies sobre un nivel inferior para trabajo en andamio (con algunas excepciones, como pump jacks)." },
  { id: "fp-11", category: "fallProtection", topic: "Montaje de acero", q: "Bajo la Subparte R, la protección contra caídas para montaje de acero se exige en general a:", choices: ["6 pies para todos los conectores", "15 pies (los conectores tienen reglas adicionales limitadas)", "30 pies", "solo a 25 pies"], a: 1, why: "1926.760: umbral general de 15 pies. Los conectores tienen disposiciones específicas entre 15 y 30 pies." },
  { id: "fp-12", category: "fallProtection", topic: "Partes del PFAS", q: "Un sistema personal de detención de caídas suele incluir:", choices: ["Casco, lentes y guantes", "Anclaje, dispositivo de conexión (eslinga o línea de vida/SRL) y arnés de cuerpo completo", "Un cinturón de cuerpo y una soga alrededor de un tubo", "Solo una línea de advertencia"], a: 1, why: "ABC: Anclaje, arnés de cuerpo, dispositivo de conexión. Los cinturones de cuerpo no se permiten para detención de caídas." },
  { id: "fp-13", category: "fallProtection", topic: "Cinturones de cuerpo", q: "Los cinturones de cuerpo pueden usarse para:", choices: ["Detención de caídas en construcción", "Posicionamiento o restricción de recorrido, pero no como arnés de detención de caídas", "Solo subir escaleras", "Cualquier caída de más de 6 pies"], a: 1, why: "OSHA prohibió los cinturones de cuerpo para detención personal de caídas porque pueden causar lesión abdominal grave. Use un arnés de cuerpo completo." },
  { id: "fp-14", category: "fallProtection", topic: "Línea de advertencia", q: "En un techo de pendiente baja, una línea de advertencia usada en lugar de protección convencional durante el techado debe estar, en general, a qué distancia del borde cuando no se usa equipo mecánico?", choices: ["3 pies", "6 pies", "15 pies", "25 pies"], a: 1, why: "1926.502(f): 6 pies desde el borde del techo sin equipo mecánico; 10 pies en los lados perpendiculares al recorrido del equipo cuando se usa equipo." },
  { id: "fp-15", category: "fallProtection", topic: "Rodapiés", q: "Los rodapiés en sistemas de barandal miden en general al menos:", choices: ["1 pulgada de alto", "3.5 pulgadas de alto", "12 pulgadas de alto", "42 pulgadas de alto"], a: 1, why: "1926.502(j): rodapiés de al menos 3.5 pulgadas, no más de 1/4 de pulgada de holgura sobre la superficie, resistencia de 50 lb." },
  { id: "fp-16", category: "fallProtection", topic: "Inspección", q: "El equipo de detención personal de caídas debe inspeccionarse:", choices: ["Solo una vez al año", "Antes de cada uso", "Solo después de una caída", "Solo por OSHA"], a: 1, why: "1926.502(d)(21): inspeccione el PFAS antes de cada uso. El equipo que detuvo una caída se retira de servicio." },
  { id: "ld-01", category: "ladders", topic: "4:1", q: "Las escaleras portátiles usadas para acceder a un nivel superior deben colocarse aproximadamente a una:", choices: ["relación 1:1 (45 grados)", "relación 4:1 — 1 pie hacia afuera por cada 4 pies de longitud de trabajo", "relación 8:1", "inclinación vertical de 90 grados contra la pared"], a: 1, why: "1926.1053(b)(5)(i): unos 75 grados, o 1:4. Una prueba común es pararse con los dedos de los pies en la base y los brazos extendidos: los rieles deben quedar cerca de las manos." },
  { id: "ld-02", category: "ladders", topic: "Extensión", q: "Cuando una escalera portátil se usa para acceder a un descanso superior, los rieles laterales deben extenderse al menos:", choices: ["1 pie por encima del descanso", "3 pies por encima del descanso", "6 pies por encima del descanso", "al ras del descanso"], a: 1, why: "1926.1053(b)(1): al menos 3 pies por encima del descanso superior, o la escalera debe asegurarse y proporcionarse un dispositivo para agarrarse." },
  { id: "ld-03", category: "ladders", topic: "Tres puntos", q: "El contacto de tres puntos en una escalera significa:", choices: ["Tres personas en la escalera", "Dos manos y un pie, o dos pies y una mano, en contacto al subir", "Tres peldaños saltados a la vez", "La escalera tocando la pared en tres puntos"], a: 1, why: "Mantenga el control al subir. No cargue cargas que impidan agarrarse con una mano." },
  { id: "ld-04", category: "ladders", topic: "Escalera de tijera", q: "En una escalera de tijera usted no debe:", choices: ["Mirar hacia la escalera", "Pararse en la tapa superior ni en el último peldaño (salvo que el fabricante haya diseñado ese peldaño para pararse)", "Asegurar los tensores", "Colocarla en suelo firme y nivelado"], a: 1, why: "La tapa superior no es un peldaño. Extenderse de más y pararse demasiado alto son causas comunes de caídas." },
  { id: "ld-05", category: "ladders", topic: "Escaleras de metal", q: "Las escaleras de metal no deben usarse:", choices: ["Al aire libre", "Donde puedan contactar equipo eléctrico energizado", "Sobre concreto", "Si tienen patas antideslizantes"], a: 1, why: "El metal conduce electricidad. Use fibra de vidrio cerca de trabajo eléctrico y mantenga distancia de las líneas." },
  { id: "ld-06", category: "ladders", topic: "Inspeccionar", q: "Las escaleras deben inspeccionarse:", choices: ["Solo al comprarlas", "Por defectos visibles antes del uso, y después de cualquier incidente que pueda afectar la resistencia", "Cada cinco años", "Solo por un ingeniero profesional"], a: 1, why: "1926.1053(b)(15): una persona competente inspecciona periódicamente; los usuarios buscan defectos antes de cada uso." },
  { id: "ld-07", category: "ladders", topic: "Inspección de andamio", q: "Los andamios deben ser inspeccionados por una persona competente:", choices: ["Una vez por proyecto", "Antes de cada turno de trabajo y después de cualquier suceso que pueda afectar la integridad estructural", "Solo después de un colapso", "Mensualmente"], a: 1, why: "1926.451(f)(3): la persona competente inspecciona antes de cada turno y después de eventos como el clima que puedan afectar el andamio." },
  { id: "ld-08", category: "ladders", topic: "Protección contra caídas en andamio", q: "Cada empleado en un andamio a más de 10 pies sobre un nivel inferior debe estar protegido por:", choices: ["Solo un casco", "Barandales y/o un sistema personal de detención de caídas según se exija para ese tipo de andamio", "Solo una línea de advertencia", "Nada si tiene 3 años de experiencia"], a: 1, why: "1926.451(g) establece las reglas de protección contra caídas en andamios. Muchos andamios apoyados usan barandales; algunos requieren PFAS." },
  { id: "ld-09", category: "ladders", topic: "Entablado", q: "Las plataformas de andamio deben estar:", choices: ["Entabladas con madera al azar de cualquier grado", "Completamente entabladas o cubiertas entre los montantes delanteros y los soportes del barandal", "Con huecos de 18 pulgadas para acceso de herramientas", "De un solo tablón de ancho a cualquier altura"], a: 1, why: "1926.451(b): completamente entabladas, tablones de grado para andamio, aberturas en general de no más de 1 pulgada salvo que se necesite más." },
  { id: "ld-10", category: "ladders", topic: "Ancho", q: "Cada plataforma y pasarela de andamio debe tener al menos qué ancho (con excepciones limitadas)?", choices: ["8 pulgadas", "12 pulgadas", "18 pulgadas", "36 pulgadas"], a: 2, why: "1926.451(b)(2): al menos 18 pulgadas de ancho. Los andamios de gato de escalera, de placa superior, de soporte de techo y pump-jack tienen excepciones específicas." },
  { id: "ld-11", category: "ladders", topic: "Amarres", q: "Los andamios apoyados con una relación altura-base de más de 4:1 deben:", choices: ["Pintarse de naranja", "Sujetarse con vientos, amarres o riostras para evitar el vuelco", "Usarse solo en interiores", "Limitarse a un trabajador"], a: 1, why: "1926.451(c)(1): sujete los andamios que de otro modo serían inestables. Los amarres suelen empezar a la altura 4:1." },
  { id: "ld-12", category: "ladders", topic: "Carga", q: "Los andamios y sus componentes deben ser capaces de soportar:", choices: ["Solo el peso de un trabajador", "Su propio peso más al menos 4 veces la carga máxima prevista", "El doble de la carga prevista", "Cualquier carga que la cuadrilla decida colocar"], a: 1, why: "1926.451(a)(1): factor de seguridad 4:1 sobre la carga máxima prevista, sin incluir el peso propio del andamio en ese multiplicador." },
  { id: "ex-01", category: "excavation", topic: "Regla de 5 pies", q: "Un sistema de protección se exige en general en excavaciones:", choices: ["De más de 2 pies de profundidad", "De 5 pies o más, salvo que la excavación esté en roca estable o una persona competente determine que no hay potencial de derrumbe", "Solo a 20 pies", "Nunca si los trabajadores usan casco"], a: 1, why: "1926.652(a): 5 pies es el umbral habitual. Menos de 5 pies igual necesita protección si una persona competente ve peligro de derrumbe." },
  { id: "ex-02", category: "excavation", topic: "Persona competente", q: "¿Quién debe inspeccionar las excavaciones a diario?", choices: ["Cualquier peón", "Una persona competente", "Solo OSHA", "El distribuidor del equipo"], a: 1, why: "1926.651(k): una persona competente inspecciona a diario, durante el turno según se necesite, y después de lluvia u otros eventos que aumenten el peligro." },
  { id: "ex-03", category: "excavation", topic: "Material excavado", q: "Los montones de material excavado y otros materiales deben mantenerse al menos a qué distancia del borde de una excavación?", choices: ["6 pulgadas", "2 pies", "6 pies", "10 pies"], a: 1, why: "1926.651(j)(2): mantenga el material excavado, las herramientas y el equipo al menos a 2 pies del borde, o use dispositivos de contención." },
  { id: "ex-04", category: "excavation", topic: "Salida", q: "En zanjas de 4 pies o más de profundidad, una escalera fija, escalera de mano, rampa u otro medio de salida debe estar a no más de:", choices: ["10 pies de recorrido lateral", "25 pies de recorrido lateral", "50 pies de recorrido lateral", "100 pies de recorrido lateral"], a: 1, why: "1926.651(c)(2): 25 pies de recorrido lateral hasta la salida en zanjas de 4 pies o más de profundidad." },
  { id: "ex-05", category: "excavation", topic: "Tipo C", q: "El suelo Tipo C — el menos estable en las tablas de excavación de OSHA — se inclina en general a no más de:", choices: ["1/2 : 1 (63 grados)", "3/4 : 1 (53 grados)", "1 : 1 (45 grados)", "1.5 : 1 (34 grados)"], a: 3, why: "Apéndice B: Tipo A 3/4:1, Tipo B 1:1, Tipo C 1½:1 para excavaciones de talud simple de menos de 20 pies." },
  { id: "ex-06", category: "excavation", topic: "20 pies", q: "Los sistemas de protección para excavaciones de 20 pies o más de profundidad deben:", choices: ["Ser iguales que en una zanja de 6 pies", "Ser diseñados por un ingeniero profesional registrado", "Omitirse si el suelo se ve seco", "Limitarse solo a talud sin diseño"], a: 1, why: "1926.652(b) y (c): a 20 pies y más, el talud, las banquetas, el escudo o el apuntalamiento deben ser diseñados por un PE o seguir datos tabulados según corresponda." },
  { id: "ex-07", category: "excavation", topic: "Servicios", q: "Antes de abrir una excavación, el empleador debe:", choices: ["Adivinar dónde están los servicios", "Determinar la ubicación de los servicios subterráneos y contactar al localizador / 811 según se exija", "Solo buscar líneas aéreas", "Cavar de noche para que haya menos tráfico"], a: 1, why: "1926.651(b): determine las instalaciones subterráneas. Llame al 811 / sistema de una llamada antes de cavar." },
  { id: "ex-08", category: "excavation", topic: "Agua", q: "El agua que se acumula en una excavación:", choices: ["Estabiliza el suelo", "Aumenta los peligros de derrumbe y ahogamiento y en general requiere controles y la evaluación de una persona competente", "Significa suelo Tipo A", "Solo es un problema por debajo de 20 pies"], a: 1, why: "1926.651(h): los empleados no pueden trabajar en excavaciones donde se acumula agua salvo que haya precauciones." },
  { id: "ex-09", category: "excavation", topic: "Atmósfera", q: "Donde razonablemente pueda existir deficiencia de oxígeno o una atmósfera peligrosa (por ejemplo, excavaciones en relleno sanitario o cerca de tanques), se exige prueba cuando la profundidad es mayor de:", choices: ["2 pies", "4 pies", "8 pies", "20 pies"], a: 1, why: "1926.651(g): pruebe antes de que los empleados entren en excavaciones de más de 4 pies si podría existir una atmósfera peligrosa." },
  { id: "ex-10", category: "excavation", topic: "Sin protección", q: "Si una zanja tiene más de 5 pies de profundidad y no tiene sistema de protección, los trabajadores deben:", choices: ["Trabajar rápido para que la exposición sea corta", "No entrar hasta que haya un sistema adecuado", "Acostarse para quedar debajo del montón de material", "Usar una tarima de madera como escudo"], a: 1, why: "Los derrumbes matan en segundos. No hay excepción de “trabaje rápido”. Primero talud, apuntalamiento o escudo." },
  { id: "el-01", category: "electrical", topic: "Distancia a líneas aéreas", q: "A menos que la línea esté desenergizada y aterrizada, mantenga a trabajadores no calificados y objetos conductores al menos a qué distancia de líneas eléctricas aéreas de hasta 50 kV?", choices: ["3 pies", "6 pies", "10 pies", "20 pies"], a: 2, why: "1910.333 y 1926.416: 10 pies para líneas de 50 kV o menos. Voltajes mayores necesitan más distancia." },
  { id: "el-02", category: "electrical", topic: "GFCI", q: "En obras de construcción, los receptáculos temporales de 120 voltios, 15 y 20 amperios, deben tener en general:", choices: ["Un GFCI o un programa asegurado de conductor de puesta a tierra del equipo", "Solo un adaptador de dos patas", "Un interruptor de 30 amperios", "Ninguna protección si está en interiores"], a: 0, why: "1926.404(b)(1): protección GFCI o un AEGCP documentado. El GFCI es la opción habitual." },
  { id: "el-03", category: "electrical", topic: "Persona calificada", q: "El trabajo en partes eléctricas energizadas, en general, solo puede hacerlo:", choices: ["Cualquier ayudante con botas de hule", "Una persona calificada usando las prácticas de trabajo seguro requeridas", "Cualquiera con tarjeta OSHA 10", "Solo el superintendente de la obra"], a: 1, why: "1910.333 / 1926 Subparte K: solo personas calificadas trabajan en o cerca de partes vivas expuestas, y se prefiere desenergizar." },
  { id: "el-04", category: "electrical", topic: "Cordones", q: "Los cordones flexibles con aislamiento dañado o sin pata de tierra deben:", choices: ["Envolverse con cinta eléctrica y seguir en servicio", "Retirarse de servicio hasta que una persona calificada los repare o se reemplacen", "Usarse solo en clima seco", "Usarse solo a menos de 50 voltios"], a: 1, why: "Los cordones dañados son una fuente principal de electrocución y choque. No “tape y espere”." },
  { id: "el-05", category: "electrical", topic: "50 voltios", q: "Las partes vivas de equipo eléctrico que opera a 50 voltios o más deben:", choices: ["Pintarse de rojo", "Resguardarse contra contacto accidental", "Ser accesibles a todos para reiniciar", "Rociarse con agua si hacen arco"], a: 1, why: "1910.303 / 1926.403: resguarde las partes vivas de 50 voltios o más por ubicación o envolventes." },
  { id: "el-06", category: "electrical", topic: "Grúas vs líneas", q: "A menos que se confirme el voltaje y se usen las distancias de la Tabla A, las operaciones de grúa deben mantener una aproximación mínima de:", choices: ["4 pies", "10 pies", "20 pies desde las líneas eléctricas aéreas", "50 pies"], a: 2, why: "1926.1408: prevención de acercamiento de 20 pies para líneas de hasta 350 kV cuando se desconoce el voltaje, o use la Tabla A si se conoce el voltaje." },
  { id: "el-07", category: "electrical", topic: "Puesta a tierra", q: "El conductor de puesta a tierra del equipo en una herramienta de cordón y enchufe:", choices: ["Es opcional si la herramienta es de doble aislamiento", "Conduce la corriente de falla para que un interruptor o GFCI despeje una falla a tierra en herramientas que requieren tierra", "Aumenta el voltaje", "Solo es para cables de datos"], a: 1, why: "Las herramientas de doble aislamiento pueden usar un cordón de dos hilos. Las herramientas con tierra necesitan una trayectoria de tierra intacta." },
  { id: "el-08", category: "electrical", topic: "Condiciones húmedas", q: "Usar herramientas eléctricas en condiciones mojadas o húmedas:", choices: ["Siempre está prohibido", "Aumenta el riesgo de choque; use GFCI, el EPP adecuado y mantenga cordones y herramientas en buen estado", "Es más seguro porque el agua aterra el circuito", "Solo importa por encima de 480 voltios"], a: 1, why: "El agua baja la resistencia. El GFCI, lugares secos para pararse y desenergizar reducen el riesgo." },
  { id: "el-09", category: "electrical", topic: "Desenergizar", q: "El método preferido antes del trabajo eléctrico es:", choices: ["Trabajar en vivo con guantes de cuero", "Desenergizar, bloquear/etiquetar y verificar la ausencia de voltaje", "Apagar solo el interruptor de luz del cuarto", "Poner cinta sobre el breaker"], a: 1, why: "1910.333 y LOTO 1910.147: desenergice salvo que se pueda demostrar inviabilidad o un peligro mayor." },
  { id: "el-10", category: "electrical", topic: "Probar", q: "Después de bloquear un circuito, antes de tocar conductores usted debe:", choices: ["Asumir que está muerto porque el interruptor está apagado", "Probar la ausencia de voltaje con un probador que se sepa que funciona", "Lamerse un dedo para ver si hay cosquilleo", "Esperar 10 segundos"], a: 1, why: "Siempre verifique. El breaker equivocado, la energía almacenada y el voltaje inducido matan a quienes “sabían” que estaba apagado." },
  { id: "pp-01", category: "ppe", topic: "Jerarquía", q: "En la jerarquía de controles, el EPP es:", choices: ["El primer y mejor control", "La última línea de defensa después de eliminación, sustitución, ingeniería y controles administrativos", "Nunca se exige si se usa casco", "Un sustituto de los resguardos de máquina"], a: 1, why: "El EPP falla si falta, es incorrecto o no se usa. Elimine el peligro con ingeniería cuando pueda." },
  { id: "pp-02", category: "ppe", topic: "Pago", q: "El empleador debe pagar la mayor parte del EPP, incluyendo:", choices: ["Solo cascos si el trabajador lo pide dos veces", "Cascos, protección auditiva y la mayoría de lentes y guantes de seguridad de especialidad que exige la norma", "Ropa cotidiana como pantalones largos", "Botas de tala en todas las industrias"], a: 1, why: "1910.132(h) / 1926.95: el empleador paga el EPP requerido con excepciones listadas (zapatos de puntera de seguridad que no son de especialidad, ropa cotidiana, lentes de receta no especiales, etc.)." },
  { id: "pp-03", category: "ppe", topic: "Excepción de pago", q: "¿Cuál artículo es un ejemplo de EPP que el empleador en general no tiene que pagar?", choices: ["Un casco de soldar requerido para el trabajo", "Botas de puntera de acero que no son de especialidad y que el empleado puede usar fuera de la obra", "Un respirador exigido por OSHA", "Guantes aislantes eléctricos"], a: 1, why: "El empleador no tiene que pagar el calzado de puntera de seguridad que no es de especialidad y que no se usa solo en el trabajo, entre una lista corta de excepciones." },
  { id: "pp-04", category: "ppe", topic: "Evaluación", q: "Antes de exigir EPP, el empleador debe:", choices: ["Comprar los lentes más baratos", "Evaluar los peligros del lugar de trabajo que requieren EPP", "Esperar una inspección de OSHA", "Dejar que cada trabajador elija cualquier lentes de sol"], a: 1, why: "1910.132(d): evaluación documentada de peligros y selección de EPP. La construcción tiene deberes paralelos de proporcionar y exigir EPP." },
  { id: "pp-05", category: "ppe", topic: "Cascos", q: "Los cascos industriales suelen certificarse según:", choices: ["ANSI/ISEA Z89.1", "solo ANSI Z87.1", "solo NFPA 70E", "ASTM D4236"], a: 0, why: "Z89.1 cubre Tipo I/II y Clases eléctricas G, E y C. Z87.1 es protección de ojos y cara." },
  { id: "pp-06", category: "ppe", topic: "Ojos", q: "Los lentes de seguridad usados para protección contra impacto deben cumplir:", choices: ["ANSI/ISEA Z87.1", "ANSI Z89.1", "Solo marcas de moda “CE”", "Ninguna norma si se ven oscuros"], a: 0, why: "Busque las marcas Z87 o Z87+. Se exige protección lateral donde hay partículas que vuelan." },
  { id: "pp-07", category: "ppe", topic: "Nivel de acción auditiva", q: "El nivel de acción de ruido de OSHA (cuando en general se exige un programa de conservación auditiva en industria general) es un TWA de 8 horas de:", choices: ["70 dBA", "85 dBA", "90 dBA", "140 dBA"], a: 1, why: "1910.95: 85 dBA TWA de 8 horas es el nivel de acción. 90 dBA es el PEL. 140 dB de pico es un límite impulsivo aparte." },
  { id: "pp-08", category: "ppe", topic: "PEL de ruido", q: "El límite de exposición permisible de OSHA para ruido es un TWA de 8 horas de:", choices: ["80 dBA", "85 dBA", "90 dBA", "100 dBA"], a: 2, why: "PEL de 90 dBA con tasa de intercambio de 5 dB. Muchos programas de seguridad igual inician la protección auditiva a 85 dBA." },
  { id: "pp-09", category: "ppe", topic: "Evaluación médica del respirador", q: "Antes de que un trabajador use un respirador de ajuste hermético, el empleador debe proporcionar:", choices: ["Solo un folleto", "Una evaluación médica", "Una radiografía de tórax en todos los casos", "Nada si el respirador es un N95"], a: 1, why: "1910.134: evaluación médica antes de la prueba de ajuste y el uso, incluso para N95 usados como respiradores (no las excepciones de uso voluntario)." },
  { id: "pp-10", category: "ppe", topic: "Prueba de ajuste", q: "Los respiradores de ajuste hermético requieren prueba de ajuste:", choices: ["Una vez en la carrera", "Al inicio y al menos anualmente, y cuando ocurran cambios faciales", "Solo si el trabajador tiene barba", "Nunca para media máscara"], a: 1, why: "1910.134(f): prueba de ajuste cualitativa o cuantitativa antes del primer uso, anualmente y después de cambios que afecten el sello." },
  { id: "pp-11", category: "ppe", topic: "Vello facial", q: "Un trabajador que debe usar un respirador de ajuste hermético:", choices: ["Puede conservar la barba completa si usa correas extra", "No puede tener vello facial entre la superficie de sello y la cara", "Está exento si firma una exención", "Solo necesita un PAPR con capucha en todos los casos"], a: 1, why: "El vello en el sello causa fugas. Afeitado en donde sella el respirador, o use un respirador de capucha de ajuste holgado si el programa lo permite." },
  { id: "pp-12", category: "ppe", topic: "Guantes", q: "Los guantes resistentes a químicos deben seleccionarse según:", choices: ["Solo el color", "El químico, el tiempo de penetración y la tarea", "Lo que haya en la caja de herramientas", "Algodón para todo solvente"], a: 1, why: "SDS Sección 8 y tablas de resistencia química del fabricante. El nitrilo no es universal." },
  { id: "pp-13", category: "ppe", topic: "Alta visibilidad", q: "Los trabajadores expuestos al tráfico vehicular público en construcción en general necesitan:", choices: ["Ninguna ropa especial", "Prendas de advertencia de alta visibilidad según exige el MUTCD / 1926.201", "Solo un casco", "Camuflaje"], a: 1, why: "1926.201 y el MUTCD exigen ropa de alta visibilidad en muchas situaciones de control de tráfico." },
  { id: "pp-14", category: "ppe", topic: "Capacitación", q: "La capacitación de EPP debe cubrir:", choices: ["Cuándo se necesita EPP, qué usar, cómo ponérselo, limitaciones y cuidado", "Solo el nombre de la marca", "Cómo facturar al cliente", "Nada si el EPP es “sentido común”"], a: 0, why: "1910.132(f): capacite y vuelva a capacitar si el trabajador demuestra que no entiende o si cambian el EPP o los peligros." },
  { id: "pp-15", category: "ppe", topic: "Dañado", q: "El EPP dañado o defectuoso debe:", choices: ["Usarse hasta el final del turno", "Retirarse de servicio", "Darse a los nuevos empleados", "Pintarse para ocultar grietas"], a: 1, why: "Los cascos agrietados, los lentes empañados o picados y los arneses deshilachados no protegen. Reemplácelos." },
  { id: "hc-01", category: "hazcom", topic: "Propósito", q: "La Norma de comunicación de peligros a menudo se llama:", choices: ["La regla de bloqueo", "La norma de derecho a saber / información al trabajador", "La norma de protección contra caídas", "La norma de espacios confinados"], a: 1, why: "1910.1200: los trabajadores tienen derecho a conocer las identidades y los peligros de los químicos con los que trabajan." },
  { id: "hc-02", category: "hazcom", topic: "SDS", q: "Las Safety Data Sheets bajo GHS tienen cuántas secciones?", choices: ["8", "12", "16", "24"], a: 2, why: "El formato SDS de GHS tiene 16 secciones. La Sección 2 es peligros; la Sección 4 primeros auxilios; la Sección 8 controles de exposición/EPP." },
  { id: "hc-03", category: "hazcom", topic: "Palabras de advertencia", q: "Las dos palabras de advertencia GHS son:", choices: ["Caution y Notice", "Danger y Warning", "Stop y Yield", "Fatal y Harmful"], a: 1, why: "Danger es más grave que Warning. No todo químico usa una palabra de advertencia." },
  { id: "hc-04", category: "hazcom", topic: "Pictogramas", q: "Los pictogramas de peligro GHS son:", choices: ["Arte opcional", "Diamantes con borde rojo y un símbolo negro sobre blanco", "Solo círculos azules", "Cuadros verdes"], a: 1, why: "OSHA exige los pictogramas estandarizados (calavera, llama, corrosión, etc.). El pictograma ambiental no es obligatorio bajo OSHA." },
  { id: "hc-05", category: "hazcom", topic: "Etiquetas secundarias", q: "Un recipiente de trabajo (secundario) en general debe etiquetarse salvo que:", choices: ["El trabajador lo use de inmediato bajo su control exclusivo y no deje restos sin marcar", "Solo contenga agua, en todos los casos incluso ácidos", "Sea un tambor de 55 galones", "El químico no sea peligroso"], a: 0, why: "Los recipientes portátiles para uso inmediato por el empleado que transfirió el químico pueden no etiquetarse. No deje químicos sin etiqueta para el siguiente turno." },
  { id: "hc-06", category: "hazcom", topic: "Programa escrito", q: "Los empleadores con químicos peligrosos deben tener:", choices: ["Un programa escrito de HazCom, inventario de químicos, acceso a SDS, etiquetas y capacitación", "Solo SDS en una oficina bajo llave", "Solo advertencias verbales", "Ningún programa si tienen menos de 10 empleados en todos los casos"], a: 0, why: "1910.1200(e): programa escrito. Las SDS deben estar fácilmente accesibles en el turno." },
  { id: "hc-07", category: "hazcom", topic: "Capacitación", q: "La capacitación de HazCom se exige:", choices: ["Solo para químicos", "Antes de asignar a un trabajador a trabajar con químicos peligrosos, y cuando se introducen nuevos peligros", "Una vez cada 10 años", "Solo después de un derrame"], a: 1, why: "Capacite sobre etiquetas, SDS, peligros de los químicos en el área de trabajo y medidas de protección." },
  { id: "hc-08", category: "hazcom", topic: "Sección 2", q: "¿Cuál sección de la SDS lista los peligros del químico, incluida la palabra de advertencia y los pictogramas?", choices: ["Sección 1 Identificación", "Sección 2 Identificación de peligros", "Sección 16 Otra información", "Sección 14 Transporte"], a: 1, why: "La Sección 2 es el resumen rápido de peligros. Aun así lea las secciones de EPP y primeros auxilios antes de usar el producto." },
  { id: "hc-09", category: "hazcom", topic: "Danger vs Warning", q: "En una etiqueta GHS, “Danger” significa:", choices: ["Un peligro menos grave que Warning", "Un peligro más grave que Warning", "Que el químico está prohibido", "Que no se necesita EPP"], a: 1, why: "Danger es la palabra de advertencia más alta. Warning se usa para categorías de peligro menos graves." },
  { id: "hc-10", category: "hazcom", topic: "Inventario", q: "Se exige un inventario (lista) de químicos para que:", choices: ["OSHA cobre por químico", "El empleador pueda emparejar las SDS con lo que realmente hay en el sitio", "Los trabajadores puedan saltarse las etiquetas", "Solo se rastreen los inflamables"], a: 1, why: "La lista es parte del programa escrito y es cómo se sabe que la cobertura de SDS está completa." },
  { id: "lo-01", category: "loto", topic: "Propósito", q: "El propósito del bloqueo y etiquetado (LOTO) es:", choices: ["Acelerar la producción", "Controlar la energía peligrosa durante el servicio y el mantenimiento para que el equipo no arranque ni libere energía", "Reemplazar de forma permanente los resguardos de máquina", "Capacitar solo a electricistas"], a: 1, why: "1910.147 cubre energía eléctrica, mecánica, hidráulica, neumática, química, térmica y de otro tipo." },
  { id: "lo-02", category: "loto", topic: "Autorizado", q: "Un empleado autorizado es alguien que:", choices: ["Pasa junto a la máquina", "Bloquea o etiqueta las máquinas para realizar el servicio", "Solo lee el procedimiento", "Es dueño de la empresa"], a: 1, why: "Los empleados autorizados aplican candados/etiquetas. Los empleados afectados operan o trabajan en el área. Los demás empleados necesitan concientización." },
  { id: "lo-03", category: "loto", topic: "Afectado", q: "Un empleado afectado debe:", choices: ["Quitar los candados de los empleados autorizados si la producción está atrasada", "Ser notificado y no intentar arrancar el equipo bloqueado", "Realizar el bloqueo sin capacitación", "Saltar el candado con una llave de repuesto"], a: 1, why: "A los empleados afectados se les informa cuándo empieza y termina el bloqueo. Ellos no aplican ni quitan los candados de servicio." },
  { id: "lo-04", category: "loto", topic: "Verificar", q: "Después de aplicar los dispositivos de bloqueo, el empleado autorizado debe:", choices: ["Asumir que la energía se fue", "Verificar el aislamiento: intentar arrancar la máquina y/o probar energía residual", "Salir del área de inmediato", "Solo quitar resguardos"], a: 1, why: "La verificación (prueba de arranque) detecta breakers equivocados, doble alimentación y energía almacenada. Devuelva los controles a apagado después de la prueba." },
  { id: "lo-05", category: "loto", topic: "Candado personal", q: "Cada empleado autorizado que trabaja en una máquina en general debe:", choices: ["Compartir un candado para toda la cuadrilla", "Aplicar su propio candado (o un control personal equivalente en un bloqueo de grupo)", "Usar siempre solo una etiqueta", "Dejar la llave en el candado"], a: 1, why: "Una persona, un candado, una llave es la idea central. El bloqueo de grupo usa una caja de candados o un hasp para que cada persona siga teniendo protección personal." },
  { id: "lo-06", category: "loto", topic: "Grupo", q: "En un bloqueo de grupo, el último candado que se quite debe ser:", choices: ["El de cualquiera", "El candado de quien verifica que la máquina está libre de trabajadores y lista para reenergizar, después de que cada trabajador haya quitado su candado personal", "Dejarse puesto para siempre", "El candado del supervisor quitado primero para que empiece la producción"], a: 1, why: "El candado primario/de cuadrilla permanece hasta que el trabajo esté despejado. Nadie queda expuesto cuando se restaura la energía." },
  { id: "lo-07", category: "loto", topic: "Energía almacenada", q: "La energía peligrosa incluye energía almacenada como:", choices: ["Solo electricidad", "Capacitores, resortes, piezas elevadas (gravedad), presión hidráulica y químicos residuales del proceso", "Solo vapor", "La luz del sol"], a: 1, why: "Alivie, desconecte, sujete o de otro modo haga segura la energía almacenada. Un breaker bloqueado no basta si un pistón puede caer." },
  { id: "lo-08", category: "loto", topic: "Cordón y enchufe", q: "El equipo de cordón y enchufe en general está exento del LOTO completo si:", choices: ["Está desenchufado y bajo el control exclusivo del empleado que realiza el trabajo", "Tiene más de 50 voltios", "Tiene un cordón rojo", "Dos personas trabajan en él"], a: 0, why: "1910.147(a)(2)(iii)(A): desenchúfelo y mantenga el enchufe bajo su control. Si se aleja, haga bloqueo o otro trabajador puede enchufarlo." },
  { id: "lo-09", category: "loto", topic: "Anual", q: "Los procedimientos de bloqueo y etiquetado deben inspeccionarse al menos:", choices: ["Mensualmente", "Anualmente", "Cada 5 años", "Nunca si no hubo lesiones"], a: 1, why: "1910.147(c)(6): inspección periódica al menos anual, incluida una revisión con los empleados autorizados." },
  { id: "lo-10", category: "loto", topic: "Candado de otra persona", q: "Usted puede quitar el candado de otra persona solo:", choices: ["Cuando necesite la máquina", "Cuando el empleador sigue un procedimiento documentado de retiro de emergencia después de verificar que la persona no está en la máquina", "Si usted es supervisor", "Si el candado es rojo"], a: 1, why: "1910.147(e)(3): pasos específicos, incluido comprobar que el empleado no está en la instalación. Nunca corte un candado a la ligera." },
  { id: "mh-01", category: "materials", topic: "Carga suspendida", q: "Los empleados no deben:", choices: ["Usar líneas de guía en cargas que puedan girar", "Trabajar bajo una carga suspendida", "Mantenerse fuera del radio de giro", "Observar una izada desde un lugar seguro"], a: 1, why: "1926.1425 / 1910.180: nunca se pare bajo una carga izada. El aparejo falla." },
  { id: "mh-02", category: "materials", topic: "Línea de guía", q: "Una línea de guía se usa para:", choices: ["Medir la profundidad de la zanja", "Controlar una carga suspendida desde un lado para que no gire ni golpee a personas u objetos", "Reemplazar una eslinga", "Bloquear una grúa"], a: 1, why: "Mantenga las manos fuera de la carga. Guíela con una soga desde fuera de la zona de caída/giro." },
  { id: "mh-03", category: "materials", topic: "Operador de grúa", q: "Los operadores de grúa de construcción en general deben estar:", choices: ["Calificados/certificados según exige 1926 Subparte CC", "Cualquier peón con licencia Clase C", "Solo titulares de tarjeta OSHA 10", "Autodidactas en la obra el mismo día"], a: 0, why: "La Subparte CC exige operadores calificados. Las reglas de certificación/calificación aplican por tipo y capacidad de grúa." },
  { id: "mh-04", category: "materials", topic: "Tabla de carga", q: "La tabla de carga de una grúa:", choices: ["Es una sugerencia", "Debe seguirse; la capacidad cambia con la longitud de pluma, el ángulo y la configuración", "Aplica solo al GVWR del camión", "Puede excederse en un 10%"], a: 1, why: "Exceder la tabla causa volcaduras y fallas de pluma. Conozca el radio, el reenvío y las deducciones." },
  { id: "mh-05", category: "materials", topic: "Estabilizadores", q: "Cuando una grúa tiene estabilizadores, estos deben:", choices: ["Usarse según el fabricante y la tabla de carga — a menudo completamente extendidos con bases en superficies firmes", "Extenderse solo de un lado", "Ser opcionales si el suelo se ve duro", "Retractarse para ahorrar espacio en cada izada"], a: 0, why: "Una instalación incorrecta es una de las principales causas de muerte con grúas. El apuntalamiento, los huecos subterráneos y la extensión parcial cambian la capacidad." },
  { id: "mh-06", category: "materials", topic: "Radio de giro", q: "El radio de giro trasero de una superestructura que rota debe:", choices: ["Pintarse pero dejarse abierto", "Barricadarse para evitar que los trabajadores queden aplastados", "Usarse como área de descanso", "Ignorarse en grúas sobre orugas"], a: 1, why: "1926.1424: impida la entrada al radio de giro. Los contrapesos aplastan a las personas contra objetos." },
  { id: "mh-07", category: "materials", topic: "Capacitación de montacargas", q: "Los operadores de camiones industriales motorizados deben estar:", choices: ["Capacitados, evaluados y certificados por el empleador antes de operar", "Licenciados directamente por OSHA", "Solo mayores de 21 años", "Capacitados solo si el montacargas levanta más de 10,000 libras"], a: 0, why: "1910.178(l): instrucción formal, capacitación práctica y evaluación. Reciclaje después de incidentes o evaluación cada 3 años." },
  { id: "mh-08", category: "materials", topic: "Inspección de montacargas", q: "Los montacargas deben examinarse:", choices: ["Anualmente", "Al menos a diario, y después de cada turno cuando se usan las 24 horas", "Solo cuando se descomponen", "Nunca si son nuevos"], a: 1, why: "1910.178(q)(7): examen diario. Retire de servicio si los defectos afectan la seguridad." },
  { id: "mh-09", category: "materials", topic: "Prueba de sonido", q: "Antes de montar una rueda abrasiva, una prueba de sonido (ring test):", choices: ["Busca grietas: un timbre claro frente a un golpe sordo", "Solo mide las RPM", "Es opcional", "Aplica solo a discos de diamante"], a: 0, why: "1910.215: golpee la rueda. Una rueda agrietada puede explotar. También compare la clasificación de RPM con la velocidad de la máquina." },
  { id: "mh-10", category: "materials", topic: "Apoyo de trabajo", q: "En una esmeriladora de banco, el apoyo de trabajo debe ajustarse a no más de:", choices: ["1/2 pulgada de la rueda", "1/8 pulgada de la rueda", "1 pulgada de la rueda", "3 pulgadas de la rueda"], a: 1, why: "1910.215(a)(4): apoyo de trabajo máximo 1/8 pulgada. Protector de lengua (arrestachispas) máximo 1/4 pulgada. Evita que la pieza se atore." },
  { id: "mh-11", category: "materials", topic: "Carga explosiva", q: "Las herramientas de carga explosiva solo pueden operarlas:", choices: ["Cualquiera de la cuadrilla", "Empleados que hayan sido capacitados", "Inspectores de OSHA", "Menores de 16 años"], a: 1, why: "1926.302(e): operadores capacitados, descargadas cuando no se usan, nunca dispare hacia materiales duros o quebradizos que puedan astillarse." },
  { id: "mh-12", category: "materials", topic: "Cilindros", q: "Los cilindros de gas comprimido en almacenamiento deben estar:", choices: ["De lado con las tapas quitadas", "Verticales, asegurados y con tapa cuando los reguladores están fuera", "Al sol junto a trapos con aceite", "Apilados como leña"], a: 1, why: "1926.350 / 1910.101: asegure en vertical, tapas de protección de válvula, protéjalos del calor y el daño." },
  { id: "mh-13", category: "materials", topic: "Oxígeno-combustible", q: "Los cilindros de oxígeno en almacenamiento deben separarse de los cilindros de gas combustible por:", choices: ["6 pulgadas", "Una distancia mínima de 20 pies, o un muro contra fuego de 5 pies de alto con clasificación de 30 minutos", "Ninguna separación si tienen tapa", "El ancho de una tarima"], a: 1, why: "1926.350(a)(10): 20 pies o una barrera de 5 pies y 30 minutos. Mantenga los aceites lejos del oxígeno." },
  { id: "mh-14", category: "materials", topic: "Aparejo", q: "Las eslingas y el herraje de aparejo deben:", choices: ["Inspeccionarse cada día antes del uso y según se necesite durante el uso; retirar el equipo dañado", "Usarse hasta que se rompan", "Anudarse para acortar una eslinga sintética", "Cargarse de golpe para probar la capacidad"], a: 0, why: "1926.251 / 1910.184: inspeccione, nunca exceda la capacidad, no haga nudos en eslingas sintéticas, protéjalas de bordes filosos." },
  { id: "mh-15", category: "materials", topic: "Capacidad", q: "La capacidad nominal de un montacargas:", choices: ["Aplica en el centro de carga especificado; una carga más larga o más alta puede reducir la capacidad", "Nunca cambia con la posición de la carga", "Puede ignorarse si el cinturón está puesto", "Se duplica cuando conduce más rápido"], a: 0, why: "La placa de datos asume un centro de carga (a menudo 24 pulgadas). Una carga larga o un mástil elevado reduce la capacidad y la estabilidad." },
  { id: "hh-01", category: "health", topic: "PEL de sílice", q: "El PEL TWA de 8 horas de OSHA para sílice cristalina respirable es:", choices: ["10 μg/m³", "25 μg/m³", "50 μg/m³", "250 μg/m³"], a: 2, why: "1926.1153 / 1910.1053: PEL de 50 μg/m³. El nivel de acción es 25 μg/m³." },
  { id: "hh-02", category: "health", topic: "Tabla 1", q: "La Tabla 1 de sílice en construcción permite al empleador:", choices: ["Ignorar la sílice si corta en húmedo sin revisar la tabla", "Seguir métodos especificados de control de exposición para tareas listadas en lugar de monitoreo de exposición en muchos casos", "Usar el barrido en seco como control principal", "Omitir respiradores siempre que haya un ventilador encendido"], a: 1, why: "Si implementa por completo la Tabla 1 (agua, recolección de polvo, cubiertas y respiradores listados), puede no necesitar medir sílice para esa tarea." },
  { id: "hh-03", category: "health", topic: "Plomo", q: "El PEL de plomo en construcción es un TWA de 8 horas de:", choices: ["10 μg/m³", "30 μg/m³", "50 μg/m³", "500 μg/m³"], a: 2, why: "1926.62: PEL de 50 μg/m³, nivel de acción de 30 μg/m³. La demolición, la soldadura en acero pintado y el chorro son de alto riesgo." },
  { id: "hh-04", category: "health", topic: "Asbesto", q: "Si encuentra material sospechoso de contener asbesto:", choices: ["Rómpalo rápido para terminar el trabajo", "No lo perturbe; deténgase y siga las reglas de asbesto con una persona competente", "Mójelo con gasolina", "Mételo en la basura doméstica"], a: 1, why: "1926.1101: trabajo Clase I–IV, persona competente, humectación, presión negativa y capacitación. Perturbar ACM sin controles dispersa fibras." },
  { id: "hh-05", category: "health", topic: "CO", q: "El monóxido de carbono es peligroso porque es:", choices: ["Verde y huele a almendras", "Incoloro, inodoro y se une a la hemoglobina de modo que no puede transportar oxígeno", "Solo un problema al aire libre", "Siempre más pesado que el aire, así que se queda en el piso"], a: 1, why: "Los generadores, calentadores y montacargas en áreas mal ventiladas matan. Use alarmas de CO y ventilación; nunca haga funcionar motores en espacios cerrados." },
  { id: "hh-06", category: "health", topic: "Calor", q: "Un enfoque básico de prevención de enfermedad por calor es:", choices: ["Trabajar a pesar del mareo para aclimatarse más rápido", "Agua, descanso, sombra y aclimatación gradual", "Solo tabletas de sal, sin agua", "Ropa oscura que no respira"], a: 1, why: "OSHA usa la Cláusula de deber general y un Programa Nacional de Énfasis sobre el calor. Los trabajadores nuevos tienen el mayor riesgo en los primeros días." },
  { id: "hh-07", category: "health", topic: "Aclimatación", q: "La aclimatación al calor significa:", choices: ["Dejar de beber agua después de la primera semana", "Aumentar poco a poco el tiempo de trabajo en el calor durante unas 1–2 semanas para que el cuerpo se adapte", "Trabajar solo de noche para siempre", "Tomar una ducha fría una vez"], a: 1, why: "La mayoría de las muertes por calor ocurren en los primeros días. Los supervisores deben reducir la carga y vigilar a los trabajadores nuevos y a los que regresan." },
  { id: "hh-08", category: "health", topic: "Ruido", q: "Se exige protección auditiva cuando las exposiciones exceden el PEL, y un programa de conservación en general se activa en:", choices: ["El nivel de acción de 85 dBA TWA en industria general", "70 dBA", "Solo 140 dBA", "Cualquier ruido a nivel de conversación"], a: 0, why: "1910.95: el nivel de acción de 85 dBA inicia el monitoreo, los audiogramas, la capacitación y el ofrecimiento de protección." },
  { id: "hh-09", category: "health", topic: "Frío", q: "La hipotermia puede ocurrir cuando:", choices: ["Solo a temperaturas bajo 0°F", "El cuerpo pierde calor más rápido de lo que lo produce — incluso en condiciones frescas, húmedas y con viento por encima de congelación", "Usted bebe agua", "Usted usa casco"], a: 1, why: "La ropa mojada y el viento quitan el calor. Observe temblores, confusión y habla arrastrada. Caliente y seque a la persona." },
  { id: "hh-10", category: "health", topic: "Cromo hexavalente", q: "Las exposiciones a cromo hexavalente son una preocupación principalmente durante:", choices: ["Trabajo de oficina", "Soldadura, corte o esmerilado de acero inoxidable o pinturas de cromato", "Usar sierras de madera en pino", "Pintura interior solo con látex"], a: 1, why: "1910.1026 / 1926.1126: cromo hexavalente del humo de soldadura de inoxidable y algunas pinturas. Ventile y use el respirador correcto." },
  { id: "hh-11", category: "health", topic: "Patógenos en sangre", q: "La Norma de patógenos transmitidos por la sangre aplica a:", choices: ["La exposición ocupacional a sangre u otros materiales potencialmente infecciosos", "Solo hospitales en Nueva York", "Solo polvo de construcción", "Exclusivamente servicio de alimentos"], a: 0, why: "1910.1030: plan de control de exposición, vacuna contra VHB, EPP y capacitación. Los proveedores de primeros auxilios en construcción pueden estar cubiertos." },
  { id: "hh-12", category: "health", topic: "Soldadura", q: "La soldadura y el corte en áreas confinadas o mal ventiladas requieren:", choices: ["Ningún control extra", "Ventilación adecuada y/o respiradores; vigile metales, ozono y asfixia", "Solo un lente más oscuro", "Oxígeno puro para “limpiar el aire”"], a: 1, why: "1926 Subparte J / 1910.252: ventile. Nunca use oxígeno para soplar un espacio. Revise recubrimientos (plomo, cadmio, cromo)." },
  { id: "hh-13", category: "health", topic: "Solventes", q: "Los solventes orgánicos pueden causar:", choices: ["Solo sequedad de la piel, nunca efectos sistémicos", "Mareo, narcosis, efectos en hígado/riñón y peligros de incendio según el químico", "Mejor función pulmonar", "Ninguna necesidad de revisar la SDS"], a: 1, why: "Use ventilación, guantes clasificados para el solvente y prácticas a prueba de explosión. Lea la SDS." },
  { id: "fr-01", category: "fire", topic: "Clase A", q: "Un incendio Clase A involucra:", choices: ["Líquidos inflamables", "Combustibles ordinarios como madera, papel y tela", "Equipo eléctrico energizado", "Metales combustibles"], a: 1, why: "A = ceniza (combustibles ordinarios). El agua y el químico seco ABC funcionan en muchos incendios Clase A." },
  { id: "fr-02", category: "fire", topic: "Clase B", q: "Un incendio Clase B involucra:", choices: ["Madera", "Líquidos y gases inflamables como gasolina, aceite y propano", "Magnesio", "Solo aceite de cocina en una freidora (Clase K)"], a: 1, why: "B = barril (líquidos). No use un chorro de manguera de agua como agente principal sobre combustible en llamas." },
  { id: "fr-03", category: "fire", topic: "Clase C", q: "Un incendio Clase C involucra:", choices: ["Equipo eléctrico energizado", "Solo papel", "Solo metales inflamables", "Solo grasa en una tina de cocina"], a: 0, why: "C = corriente. Desenergice si puede. Use un extintor no conductor. Después de cortar la energía, puede volverse Clase A o B." },
  { id: "fr-04", category: "fire", topic: "PASS", q: "PASS para un extintor portátil significa:", choices: ["Pull, Aim, Squeeze, Sweep (Jale, Apunte, Apriete, Barrido)", "Push, Alert, Stop, Sprint", "Point, Advance, Spray, Stop", "Pull alarm, Assemble, Stay, Shelter"], a: 0, why: "Jale el pasador, apunte a la base, apriete, barre de lado a lado. Combata solo un incendio pequeño con una ruta de escape clara." },
  { id: "fr-05", category: "fire", topic: "Ancho de salida", q: "Una ruta de salida debe tener al menos qué ancho en todos los puntos?", choices: ["18 pulgadas", "22 pulgadas", "28 pulgadas", "48 pulgadas siempre, sin excepciones"], a: 2, why: "1910.36(g)(2): mínimo 28 pulgadas. La carga de ocupantes puede exigir más. Manténgala despejada." },
  { id: "fr-06", category: "fire", topic: "Salidas con candado", q: "Las puertas de salida que deben usarse en una emergencia:", choices: ["Pueden encadenarse en horario laboral para evitar robos", "Deben poder abrirse desde adentro sin llaves, herramientas ni conocimientos especiales", "Pueden bloquearse con tarimas si están rotuladas", "Son opcionales en almacenes"], a: 1, why: "1910.36(d): herraje antipánico o operación simple. Las salidas cerradas/bloqueadas son una citación frecuente y matan en incendios." },
  { id: "fr-07", category: "fire", topic: "EAP", q: "Un Plan de acción de emergencia en general incluye:", choices: ["Solo una lista telefónica de nómina", "Procedimientos de evacuación, sistema de alarma, áreas de reunión y funciones como quién se queda para apagar operaciones críticas", "Solo un mapa del estacionamiento", "Nada escrito si siempre tiene menos de 500 empleados"], a: 1, why: "1910.38: EAP escrito si tiene más de 10 empleados. Capacite a todos. La construcción usa 1926.35." },
  { id: "fr-08", category: "fire", topic: "Distancia de recorrido A", q: "La distancia máxima de recorrido hasta un extintor Clase A es en general:", choices: ["25 pies", "50 pies", "75 pies", "200 pies"], a: 2, why: "1910.157(d)(2): 75 pies para Clase A. Clase B es 50 pies." },
  { id: "fr-09", category: "fire", topic: "Revisión mensual", q: "Los extintores portátiles deben inspeccionarse visualmente:", choices: ["Una vez por década", "Mensualmente", "Solo después del uso", "Nunca si tienen etiqueta"], a: 1, why: "1910.157(e): inspección visual mensual más mantenimiento anual. Revise presión, pasador y acceso." },
  { id: "fr-10", category: "fire", topic: "Trabajo en caliente", q: "El trabajo en caliente (soldadura, corte, esmerilado que puede iniciar incendios) debe incluir:", choices: ["Ninguna precaución si tiene un vigía de incendio “en mente”", "Retirar o proteger combustibles, un vigía de incendio cuando se exija, y extintores", "Solo trabajar más rápido", "Usar oxígeno para soplar polvo"], a: 1, why: "1910.252 / 1926 Subparte J: vigía de incendio al menos 30 minutos después del trabajo en caliente en muchos casos. Los permisos son un control común del empleador." },
  { id: "ww-01", category: "walking", topic: "Orden y limpieza", q: "El orden y la limpieza en superficies de trabajo y circulación significa:", choices: ["Solo una limpieza profunda mensual", "Mantener los pisos limpios, secos en lo posible y libres de desorden que cause resbalones, tropiezos y caídas", "Guardar madera en los pasillos para ahorrar tiempo", "Dejar el desperdicio hasta la desmovilización"], a: 1, why: "1910.22 / 1926.25: orden y limpieza regulares. Los escombros de construcción son una fuente principal de tropiezos." },
  { id: "ww-02", category: "walking", topic: "Pasillos", q: "Los pasillos y las vías de paso deben:", choices: ["Mantenerse despejados y en buen estado", "Usarse para almacenar tarimas extra", "Bloquearse durante el inventario", "Ser opcionales en almacenes"], a: 0, why: "1910.22(d) / 1926.25: mantenga el acceso. Marque los pasillos permanentes donde se exija." },
  { id: "ww-03", category: "walking", topic: "Cordones", q: "Los cordones y las mangueras a través de las pasarelas:", choices: ["Son la mejor forma de protegerlos", "Crean peligros de tropiezo y deben desviarse, cubrirse o suspenderse", "Los exige OSHA", "Solo importan en las escaleras"], a: 1, why: "Eleve, cubra con un protector de cordón o desvíe. No cree un tropiezo nuevo para evitar un tendido de cordón un poco más largo." },
  { id: "ww-04", category: "walking", topic: "Huecos", q: "Los huecos en el piso deben:", choices: ["Dejarse abiertos para que se noten", "Resguardarse o cubrirse", "Marcarse solo con gis", "Permitirse si son más pequeños que una bota"], a: 1, why: "1910.28 / 1926.501: proteja los huecos. Las cubiertas deben asegurarse y marcarse. Las personas caen por tragaluces y aberturas sin resguardo." },
  { id: "ww-05", category: "walking", topic: "Escaleras fijas", q: "Las escaleras fijas con cuatro o más contrahuellas (o que suben más de 30 pulgadas) en general necesitan:", choices: ["Ningún barandal si las usan cuadrillas de construcción", "Sistemas de barandal de escalera / pasamanos según se exija", "Una escalera de mano en su lugar", "Solo una línea de advertencia"], a: 1, why: "1910.25 / 1926.1052: pasamanos y barandales de escalera. La altura uniforme de contrahuella también importa." },
  { id: "ww-06", category: "walking", topic: "Clima", q: "El hielo, el lodo y los pisos mojados deben:", choices: ["Ignorarse hasta que alguien se caiga", "Limpiarse, tratarse o marcarse, y dar calzado con tracción a los trabajadores cuando se necesite", "Cubrirlos con cartón como solución permanente", "Usarse para frenar los montacargas de forma natural"], a: 1, why: "Los resbalones se pueden prevenir. Sal/arena en el hielo, quite el agua con jalador y use tapetes. El cartón oculta peligros y se pone resbaloso." },
  { id: "ww-07", category: "walking", topic: "Salidas despejadas", q: "Los materiales no pueden almacenarse de un modo que:", choices: ["Bloquee salidas, equipo contra incendio o el acceso a paneles eléctricos", "Se vea ordenado", "Use racks", "Esté rotulado"], a: 0, why: "Mantenga el egreso y el equipo de emergencia al alcance. 1910.37 y las reglas de orden y limpieza se superponen aquí." }
];
